// Regenerates src/shared/lib/supabase/database.types.ts from the linked
// Supabase project. Plain Node so it behaves the same on every shell.
import { execSync } from "node:child_process"
import { writeFileSync } from "node:fs"

const output = execSync("pnpm exec supabase gen types typescript --linked", {
  encoding: "utf8",
})

const banner =
  "// AUTO-GENERATED by `pnpm supabase:types` -- do not edit by hand.\n"

writeFileSync("src/shared/lib/supabase/database.types.ts", banner + output)
